import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import listItems from 'flarum/common/helpers/listItems';
import { t, label, locale, collectionUrl } from '../util';
import { fieldValue } from '../../common/labels';
import { typeBadge, backdrop, conditionText } from './bits';
import ItemModal from './ItemModal';
import addToMyCollection from '../copyItem';
import useStyles from '../styles';

/** The hero of a "Show it off" discussion: the member's item, cover, details and what the forum knows about it. */
export default class ItemHero extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
  }
  view() {
    const {
      discussion,
      item
    } = this.attrs;
    const collection = item.collection();
    const type = collection?.type();
    const work = item.work();
    const owner = collection?.user();
    const cover = (item.photos() || [])[0]?.url || work?.coverUrl() || item.coverUrl();
    const badges = discussion.badges().toArray();
    const fields = type ? type.fields() || [] : [];
    const values = item.fields() || {};
    const about = work && work.description();
    const mine = app.session.user && owner === app.session.user;
    const canAdd = !mine && app.session.user && app.forum.attribute('canCreateCurio');
    const facts = [];
    if (item.condition()) facts.push([t('item.condition'), conditionText(type, item.condition())]);
    if (type?.grading() && item.graded()) facts.push([t('item.graded'), t('item.yes')]);
    if (item.acquiredOn()) facts.push([t('item.acquired'), dayjs(item.acquiredOn()).format('LL')]);
    if (item.ownersCount()) facts.push([t('hero.here'), t('hero.members', {
      count: item.ownersCount()
    })]);
    return m("header", {
      className: "Hero DiscussionHero CurioItemHero",
      style: {
        '--curio-accent': type?.color()
      }
    }, cover ? m("div", {
      className: "CurioItemHero-backdrop",
      style: {
        backgroundImage: `url(${cover})`
      }
    }) : null, m("div", {
      className: "container CurioItemHero-inner"
    }, m("button", {
      type: "button",
      className: 'CurioItemHero-cover CurioItemHero-cover--' + (type?.shape() || 'portrait'),
      onclick: () => app.modal.show(ItemModal, {
        itemId: item.id()
      }),
      "aria-label": t('hero.open_item'),
      style: backdrop(cover)
    }, cover ? m("img", {
      src: cover,
      alt: item.displayTitle()
    }) : m(Icon, {
      name: type?.icon() || 'fas fa-box-open'
    }), (item.photos() || []).length > 1 ? m("span", {
      className: "CurioItem-photoCount"
    }, m(Icon, {
      name: "fas fa-camera"
    }), " ", item.photos().length) : null), m("div", {
      className: "CurioItemHero-body"
    }, badges.length ? m("ul", {
      className: "DiscussionHero-badges badges"
    }, listItems(badges)) : null, m("div", {
      className: "CurioItemHero-kicker"
    }, typeBadge(type, 'CurioTypeBadge--solid', true), collection ? m(Link, {
      href: collectionUrl(collection)
    }, t('hero.from', {
      name: collection.name()
    })) : null), m("h1", {
      className: "DiscussionHero-title"
    }, discussion.title()), m("div", {
      className: "CurioItemHero-item"
    }, [item.displayTitle(), item.year(), item.subtitle()].filter(Boolean).join(' · ')), m("div", {
      className: "CurioItemHero-chips"
    }, fields.map(f => {
      const v = values[f.key];
      if (v === undefined || v === null || v === '' || v === false) return null;
      return m("span", {
        className: "CurioChip"
      }, f.kind === 'bool' ? m('[', null, m(Icon, {
        name: "fas fa-check"
      }), " ", label(f.labels)) : fieldValue(f, v, locale()));
    })), facts.length ? m("div", {
      className: "CurioItemHero-stats"
    }, facts.map(([k, v]) => m("div", null, m("span", null, k), m("b", null, v)))) : null, about ? m("p", {
      className: "CurioItemHero-about"
    }, about.length > 340 ? about.slice(0, about.lastIndexOf(' ', 330)) + ' …' : about) : null, m("div", {
      className: "CurioItemHero-actions"
    }, collection ? m(Link, {
      className: "Button Button--primary",
      href: collectionUrl(collection) + '?item=' + item.id()
    }, m(Icon, {
      name: "fas fa-boxes-stacked",
      className: "Button-icon"
    }), m("span", {
      className: "Button-label"
    }, mine ? t('hero.in_my_collection') : t('hero.view_in', {
      name: owner ? owner.displayName() : ''
    }))) : null, canAdd ? m(Button, {
      className: "Button CurioHero-ghost",
      icon: "fas fa-plus",
      onclick: () => addToMyCollection({
        prefill: item,
        typeIds: [type.id()]
      })
    }, t('item.have_too')) : null, canAdd ? m(Button, {
      className: "Button CurioHero-ghost",
      icon: "far fa-heart",
      onclick: () => addToMyCollection({
        prefill: item,
        status: 'wishlist',
        typeIds: [type.id()]
      })
    }, t('item.want_it')) : null, about && work.descriptionSource() === 'wikipedia' ? m("a", {
      className: "CurioItemHero-credit",
      href: work.sourceUrl(),
      target: "_blank",
      rel: "noopener noreferrer"
    }, m(Icon, {
      name: "fab fa-wikipedia-w"
    }), " ", t('item.from_wikipedia')) : null))));
  }
}
flarum.reg.add('ernestdefoe-curio', 'forum/components/ItemHero', ItemHero);